// 진료 요약 "수행 이력" 상자 아이콘 (Figma Page 3 에서 SVG 로 내보낸 것). 검정으로 그리고 tint 로 색을 입혀요.

private fun fillIcon(name: String, w: Float, h: Float, d: String) =
    ImageVector.Builder(name, w.dp, h.dp, w, h)
        .addPath(PathParser().parsePathString(d).toNodes(), fill = SolidColor(Color.Black))
        .build()

